CREATE OR REPLACE FUNCTION public.accumulate_neuron_call() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.cloudflare_neuron_usage(provider_id,day,neurons_used,exhausted,updated_at) VALUES(NEW.provider_id,(NEW.created_at AT TIME ZONE 'UTC')::date,NEW.neurons,NEW.neurons>=9500,now()) ON CONFLICT(provider_id,day) DO UPDATE SET neurons_used=public.cloudflare_neuron_usage.neurons_used+EXCLUDED.neurons_used,exhausted=public.cloudflare_neuron_usage.exhausted OR public.cloudflare_neuron_usage.neurons_used+EXCLUDED.neurons_used>=9500,updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER neuron_call_accumulate AFTER INSERT ON public.neuron_call_ledger FOR EACH ROW EXECUTE FUNCTION public.accumulate_neuron_call();